[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$CanaryReceipt,[string]$ReleaseRoot)
$ErrorActionPreference='Stop'
$project=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
$canaryPath=(Resolve-Path -LiteralPath $CanaryReceipt).Path
$canary=Get-Content -Raw -LiteralPath $canaryPath | ConvertFrom-Json
if($canary.status -ne 'passed' -or $canary.worker.workerVersion -ne '2.2.0' -or $canary.realMcpCalled){throw 'Only passed offline export.remnote 2.2.0 receipt is admissible'}
$stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssZ')
if([string]::IsNullOrWhiteSpace($ReleaseRoot)){$ReleaseRoot=Join-Path $project "releases\knowledge-clipper-remnote-exporter-v2.2.0-$stamp\win-x64"}
$ReleaseRoot=[IO.Path]::GetFullPath($ReleaseRoot);if(Test-Path -LiteralPath $ReleaseRoot){throw "Append-only release exists: $ReleaseRoot"};New-Item -ItemType Directory -Path $ReleaseRoot|Out-Null
function Write-Utf8([string]$p,[string]$v){[IO.File]::WriteAllText($p,$v,[Text.UTF8Encoding]::new($false))}
function RelEvidence([string]$p){$i=Get-Item -LiteralPath $p;[ordered]@{path=[IO.Path]::GetRelativePath($ReleaseRoot,$i.FullName).Replace('\','/');sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $i.FullName).Hash;bytes=$i.Length}}
$map=[ordered]@{
 'KnowledgeClipper.RemNoteExporter.Worker.exe'='workers\remnote\KnowledgeClipper.RemNoteExporter.Worker.exe';'appsettings.json'='workers\remnote\appsettings.json';'README.md'='workers\remnote\README.md';
 'contracts/remnote-original-media.v2.schema.json'='contracts\remnote-original-media.v2.schema.json';'contracts/remnote-export-payload.v3.schema.json'='contracts\remnote-export-payload.v3.schema.json';'contracts/remnote-export-task.v3.schema.json'='contracts\remnote-export-task.v3.schema.json';'contracts/remnote-write-receipt.v3.schema.json'='contracts\remnote-write-receipt.v3.schema.json';'contracts/remnote-public-probe-request.v2.schema.json'='contracts\remnote-public-probe-request.v2.schema.json';'contracts/remnote-public-probe-result.v2.schema.json'='contracts\remnote-public-probe-result.v2.schema.json';'contracts/remnote-destination-companion-descriptor.v2.schema.json'='contracts\remnote-destination-companion-descriptor.v2.schema.json';
 'contracts/remnote-export-payload.v2.schema.json'='contracts\remnote-export-payload.v2.schema.json';'contracts/remnote-export-task.v2.schema.json'='contracts\remnote-export-task.v2.schema.json';'contracts/remnote-write-receipt.v2.schema.json'='contracts\remnote-write-receipt.v2.schema.json';'contracts/remnote-destination-settings.v1.schema.json'='contracts\remnote-destination-settings.v1.schema.json';'contracts/remnote-destination-settings-snapshot.v1.schema.json'='contracts\remnote-destination-settings-snapshot.v1.schema.json';'contracts/remnote-readonly-probe-request.v1.schema.json'='contracts\remnote-readonly-probe-request.v1.schema.json';'contracts/remnote-readonly-probe-result.v1.schema.json'='contracts\remnote-readonly-probe-result.v1.schema.json'
}
foreach($e in $map.GetEnumerator()){$d=Join-Path $ReleaseRoot $e.Key;$parent=Split-Path -Parent $d;if(!(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Path $parent|Out-Null};Copy-Item -LiteralPath (Join-Path $project $e.Value) -Destination $d}
$evidenceDir=Join-Path $ReleaseRoot 'evidence';New-Item -ItemType Directory -Path $evidenceDir|Out-Null
Copy-Item -LiteralPath $canaryPath -Destination (Join-Path $evidenceDir 'offline-canary-receipt.json')
$canaryDir=Split-Path -Parent $canaryPath
foreach($n in @('readable-report.md','settings-companion-descriptor-v2.json','public-probe-request.json','public-probe-result.json','fake-original-media-readback.json','additive-schema-validation.log','public-contract-validation.json')){Copy-Item -LiteralPath (Join-Path $canaryDir $n) -Destination (Join-Path $evidenceDir $n)}
$worker=Join-Path $ReleaseRoot 'KnowledgeClipper.RemNoteExporter.Worker.exe';$workerHash=(Get-FileHash -Algorithm SHA256 -LiteralPath $worker).Hash
if($workerHash -ne $canary.worker.executable.sha256){throw 'worker hash drift'}
$payloadFiles=@(Get-ChildItem -LiteralPath $ReleaseRoot -Recurse -File|Sort-Object FullName|ForEach-Object{RelEvidence $_.FullName})
$material=($payloadFiles|ForEach-Object{"$($_.path)`t$($_.sha256)`t$($_.bytes)"})-join "`n";$sha=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($material)))
$manifestPath=Join-Path $ReleaseRoot 'release-manifest.json';$manifest=[ordered]@{schemaVersion='knowledge-clipper-remnote-exporter-release-manifest.v1';releaseId="knowledge-clipper-remnote-exporter-v2.2.0-$stamp";workerId='export.remnote';workerVersion='2.2.0';platform='win-x64';additive=$true;frozenCommonV1Modified=$false;payloadTreeSha256=$sha;files=$payloadFiles};Write-Utf8 $manifestPath (($manifest|ConvertTo-Json -Depth 12)+"`n")
$receiptPath=Join-Path $ReleaseRoot 'release-receipt.json';$receipt=[ordered]@{schemaVersion='knowledge-clipper-remnote-exporter-release-receipt.v1';status='passed';releaseId=$manifest.releaseId;releaseRoot=$ReleaseRoot;worker=[ordered]@{workerId='export.remnote';workerVersion='2.2.0';executableSha256=$workerHash};contracts=[ordered]@{companion='remnote-destination-companion-descriptor.v2';publicProbeRequest='remnote-public-probe-request.v2';publicProbeResult='remnote-public-probe-result.v2';originalMedia='remnote-original-media.v2';payload='3.0.0';receipt='3.0.0'};sourceCanary=[ordered]@{path=$canaryPath;sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $canaryPath).Hash};manifest=[ordered]@{path=$manifestPath;sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $manifestPath).Hash};payloadTreeSha256=$sha;productionOriginalMedia='unsupported-fail-closed';authorityRegistryAdmission='pending-core-owned-checkpoint';createdAt=[DateTime]::UtcNow.ToString('o')};Write-Utf8 $receiptPath (($receipt|ConvertTo-Json -Depth 10)+"`n");Write-Output $receiptPath
